function cleanRows(rows) {
  const clean = [], quarantined = [];
  for (const r of rows) {
    if (r.price === null || r.price === undefined || r.price === '') {
      quarantined.push({ id: r.id, reason: 'missing-price' });
      continue;
    }
    clean.push({ ...r, qty: r.qty == null ? 1 : r.qty });
  }
  const revenue = clean.reduce((s, r) => s + r.price * r.qty, 0);
  return { kept: clean.length, quarantined, revenue };
}
const r = cleanRows([
  { id: 1, price: 129, qty: 2 },
  { id: 2, price: null, qty: 1 },
  { id: 3, price: 59.5 },
]);
console.log('kept=' + r.kept + ' quarantined=' + r.quarantined.length);
console.log('reasons=' + r.quarantined.map((q) => q.reason).join(','));
console.log('revenue=' + r.revenue);

